package br.com.notedarck.esconde;

import org.bukkit.command.*;
import org.bukkit.entity.Player;
import java.util.*;

public final class EscondeCommand implements CommandExecutor, TabCompleter {
    private final EscondeEscondePlugin plugin;
    EscondeCommand(EscondeEscondePlugin plugin) { this.plugin=plugin; }
    @Override public boolean onCommand(CommandSender s, Command c, String label, String[] a) {
        if (a.length==0 || a[0].equalsIgnoreCase("help") || a[0].equalsIgnoreCase("ajuda")) { help(s); return true; }
        String sub=a[0].toLowerCase(Locale.ROOT);
        if (sub.equals("entrar")||sub.equals("join")) { Player p=player(s); if(p==null)return true; boolean explicit=a.length>1&&!a[1].equalsIgnoreCase("sorteado")&&!a[1].equalsIgnoreCase("random"); String id=explicit?a[1]:bestArena(); ArenaDefinition definition=id==null?null:plugin.arenas().get(id); if(definition==null){plugin.msg(s,"no-arena",Map.of());return true;} if(!definition.ready()){plugin.msg(s,"arena-not-ready",Map.of("arena",definition.id(),"missing",String.join(", ",definition.missingPoints())));return true;} if(!plugin.games().join(p,id)) plugin.msg(s, explicit?"arena-busy":"no-arena",Map.of("arena",id)); return true; }
        if (sub.equals("sair")||sub.equals("leave")) { Player p=player(s); if(p!=null&&!plugin.games().leave(p)) s.sendMessage("§cVocê não está em uma arena."); return true; }
        if (sub.equals("status")) { if(a.length>1){ArenaGame g=plugin.games().game(a[1]); if(g==null){plugin.msg(s,"no-arena",Map.of());return true;} s.sendMessage("§6"+g.id()+" §7| Estado: §f"+g.state()+" §7| Jogadores: §f"+g.players()+" §7| Rodada: §f"+g.hiders()+" escondidos / "+g.hunters()+" procuradores");} else for(ArenaGame g:plugin.games().all())s.sendMessage("§6"+g.id()+" §7| §f"+g.state()+" §7| jogadores: §f"+g.players()); return true; }
        if (sub.equals("arena")||sub.equals("mapa")) return arenaCommand(s,a);
        if (!s.hasPermission("esconde.admin")) { plugin.msg(s,"no-permission",Map.of()); return true; }
        if (sub.equals("iniciar")||sub.equals("start")) { if(!s.hasPermission("esconde.admin.start")){plugin.msg(s,"no-permission",Map.of());return true;} if(a.length<2){s.sendMessage("§cUso: /esconde iniciar <arena>");return true;} ArenaGame g=plugin.games().game(a[1]);if(g==null||g.players()<gDef(g).minPlayers()){plugin.msg(s,"no-arena",Map.of());return true;}plugin.games().start(a[1]);return true; }
        if (sub.equals("parar")||sub.equals("stop")) { if(!s.hasPermission("esconde.admin.stop")){plugin.msg(s,"no-permission",Map.of());return true;} if(a.length<2){s.sendMessage("§cUso: /esconde parar <arena>");return true;}plugin.games().stop(a[1]);return true; }
        if (sub.equals("reload")) { if (plugin.games().anyActive()) { s.sendMessage("§cPare as partidas antes de recarregar."); return true; } plugin.reloadAll(); s.sendMessage("§aConfiguração e arenas recarregadas."); return true; }
        return help(s);
    }
    private boolean arenaCommand(CommandSender s,String[] a){if(!s.hasPermission("esconde.admin.maps")){plugin.msg(s,"no-permission",Map.of());return true;}if(a.length<2){s.sendMessage("§e/ esconde arena listar|criar|remover|info|set");return true;}String op=a[1].toLowerCase(Locale.ROOT);if(op.equals("listar")){for(ArenaDefinition d:plugin.arenas().all())s.sendMessage("§6"+d.id()+" §7| habilitada: "+d.enabled()+" §7| pronta: "+d.ready());return true;}if(op.equals("criar")&&a.length>=3){if(plugin.arenas().create(a[2])){plugin.games().syncArenas();plugin.msg(s,"created",Map.of("arena",a[2]));}else s.sendMessage("§cEssa arena já existe ou o nome é inválido.");return true;}if(op.equals("remover")&&a.length>=3){if(plugin.arenas().remove(a[2])){plugin.games().syncArenas();plugin.msg(s,"removed",Map.of("arena",a[2]));}else s.sendMessage("§cNão é possível remover: arena inexistente ou em funcionamento.");return true;}if(op.equals("info")&&a.length>=3){ArenaDefinition d=plugin.arenas().get(a[2]);if(d==null){plugin.msg(s,"no-arena",Map.of());return true;}s.sendMessage("§6Arena §f"+d.id()+" §7| pronta: "+d.ready()+" | jogadores: "+d.minPlayers()+"-"+d.maxPlayers()+" | rodadas: "+d.rounds()+" | duração: "+d.roundSeconds()+"s");return true;}if(op.equals("set")&&a.length>=4){Player p=player(s);ArenaDefinition d=plugin.arenas().get(a[2]);if(p==null||d==null){plugin.msg(s,"no-arena",Map.of());return true;}String key=switch(a[3].toLowerCase(Locale.ROOT)){case "lobby"->"lobby";case "hider","escondedor","escondidos"->"hider-spawn";case "hunter","procurador","procuradores"->"hunter-spawn";case "spectator","espectador"->"spectator-spawn";case "exit","saida","spawn"->"exit";case "pos1"->"pos1";case "pos2"->"pos2";default->null;};if(key==null){s.sendMessage("§cPonto inválido: lobby, hider, hunter, spectator, exit, pos1 ou pos2.");return true;}d.setLocation(key,p.getLocation());plugin.saveConfig();s.sendMessage("§aPonto salvo na arena §f"+d.id()+"§a.");return true;}s.sendMessage("§cUso: /esconde arena listar|criar <nome>|remover <nome>|info <nome>|set <nome> <ponto>");return true;}
    private ArenaDefinition gDef(ArenaGame g){return plugin.arenas().get(g.id());}
    private String bestArena(){List<ArenaDefinition> choices=plugin.arenas().all().stream().filter(d->d.enabled()&&d.ready()&&plugin.games().game(d.id()).players()<d.maxPlayers()).toList();if(choices.isEmpty())return null;int max=choices.stream().mapToInt(d->plugin.games().game(d.id()).players()).max().orElse(0);List<ArenaDefinition> preferred=choices.stream().filter(d->plugin.games().game(d.id()).players()==max).toList();return preferred.get(new Random().nextInt(preferred.size())).id();}
    private Player player(CommandSender s){if(s instanceof Player p)return p;s.sendMessage("§cEste comando precisa ser executado por um jogador.");return null;}
    private boolean help(CommandSender s){s.sendMessage("§6§lEsconde-Esconde §7| comandos:");s.sendMessage("§f/esconde entrar [arena|sorteado] §7- entrar na fila");s.sendMessage("§f/esconde sair §7- sair da arena atual");s.sendMessage("§f/esconde status [arena] §7- ver partidas");s.sendMessage("§f/esconde ajuda §7- mostrar esta ajuda");if(s.hasPermission("esconde.admin")){s.sendMessage("§e/esconde iniciar <arena> §7| §e/esconde parar <arena>");s.sendMessage("§e/esconde arena listar|criar|remover|info|set <arena> <ponto>");s.sendMessage("§e/esconde reload");}return true;}
    @Override public List<String> onTabComplete(CommandSender s,Command c,String alias,String[] a){List<String> subs=List.of("entrar","sorteado","sair","status","ajuda","arena","iniciar","parar","reload");if(a.length==1)return subs.stream().filter(x->x.startsWith(a[0].toLowerCase())).toList();if(a[0].equalsIgnoreCase("arena")){if(a.length==2)return List.of("listar","criar","remover","info","set");if(a.length==3&&List.of("remover","info","set").contains(a[1].toLowerCase()))return plugin.arenas().all().stream().map(ArenaDefinition::id).toList();if(a.length==4&&a[1].equalsIgnoreCase("set"))return List.of("lobby","hider","hunter","spectator","exit","pos1","pos2");}if(a.length==2&&(a[0].equalsIgnoreCase("entrar")||a[0].equalsIgnoreCase("iniciar")||a[0].equalsIgnoreCase("parar")||a[0].equalsIgnoreCase("status")))return plugin.arenas().all().stream().map(ArenaDefinition::id).toList();return List.of();}
}
